import { useCallback, useEffect, useState } from 'react'

import type { TodoViewModel } from '../../application/TodoViewModel'
import { useTodosUseCases } from '../useTodosUseCases/useTodosUseCases'

export type TodosState =
  | { readonly status: 'loading' }
  | { readonly status: 'loaded'; readonly todos: TodoViewModel[] }
  | { readonly status: 'failed' }

export type TodosView = {
  readonly state: TodosState
  readonly message: string | null
  readonly complete: (id: string) => void
}

const markDone = (state: TodosState, id: string): TodosState =>
  state.status === 'loaded'
    ? {
        status: 'loaded',
        todos: state.todos.map((todo) => (todo.id === id ? { ...todo, status: 'done' } : todo)),
      }
    : state

export const useTodos = (): TodosView => {
  const { listTodos, completeTodo } = useTodosUseCases()
  const [state, setState] = useState<TodosState>({ status: 'loading' })
  const [message, setMessage] = useState<string | null>(null)

  useEffect(() => {
    const controller = new AbortController()
    listTodos.execute(controller.signal).then(
      (todos) => setState({ status: 'loaded', todos }),
      () => {
        if (!controller.signal.aborted) setState({ status: 'failed' })
      },
    )
    return () => controller.abort()
  }, [listTodos])

  const complete = useCallback(
    (id: string) => {
      setMessage(null)
      completeTodo.execute(id).then(
        (result) => {
          setState((current) => markDone(current, id))
          if (result === 'already-completed') setMessage('This todo is already completed.')
        },
        () => setMessage('The todo could not be completed.'),
      )
    },
    [completeTodo],
  )

  return { state, message, complete }
}
