import { TodoAlreadyCompletedError, type TodoGateway } from './TodoGateway'

export type CompleteTodoResult = 'completed' | 'already-completed'

export class CompleteTodo {
  private readonly todos: TodoGateway

  constructor(todos: TodoGateway) {
    this.todos = todos
  }

  async execute(id: string, signal?: AbortSignal): Promise<CompleteTodoResult> {
    try {
      await this.todos.complete(id, signal)
      return 'completed'
    } catch (error) {
      if (error instanceof TodoAlreadyCompletedError) return 'already-completed'
      throw error
    }
  }
}
